/* Keep the tool in the opening viewport on common portrait screens.
   Very short landscape windows can scroll; the game has no deadline. */
.game {
  width: min(100%, calc((100svh - 265px) * .580645));
  min-width: min(260px, 100%);
  margin-inline: auto;
}

.stage { container-type: inline-size; }
.balloon-body {
  padding: 4cqw 4.5cqw;
  transform: scale(calc(.35 + var(--air) * .65));
  animation: inflate .45s ease-out;
}
.balloon-small .balloon-body { padding: 3.8cqw; }
.balloon-topline { font-size: clamp(8px, 2.7cqw, 10px); }
.badge { font-size: clamp(8px, 2.5cqw, 10px); }
.balloon h2 {
  font-size: 7.2cqw;
  margin-top: 3.2cqw;
  margin-bottom: 1.5cqw;
  letter-spacing: -.35cqw;
}
.balloon-small h2 { font-size: 6.5cqw; margin-top: 2.7cqw; }
.balloon p { font-size: clamp(7px, 2.6cqw, 10px); }
.balloon-progress { font-size: clamp(7px, 2.4cqw, 9px); }
.balloon.cleared .balloon-body { pointer-events: none; }
.quiet-copy strong { font-size: 6cqw; }
.tool-tray { padding: 3cqw; font-size: clamp(9px, 2.8cqw, 11px); }
.tool-tray .tray-step { display: none; }
.feedback { min-height: 62px; padding: 10px 12px; }
.feedback p { font-size: 10px; }
.finish h2 { font-size: 6.8cqw; }

@keyframes inflate {
  from { transform: scale(.82); opacity: .65; }
  to { transform: scale(1); opacity: 1; }
}

@media (max-height: 740px) {
  .shell { padding-top: 12px; }
  .page-header { margin-bottom: 14px; }
  .intro > p:last-child { margin-bottom: 12px; }
  .eyebrow { margin-bottom: 5px; }
  h1 { font-size: 23px; margin-bottom: 8px; }
  .game { width: min(100%, calc((100svh - 225px) * .580645)); }
}

@media (prefers-reduced-motion: reduce) {
  .balloon-body { animation: none; transition: none; }
}

