(() => {
  'use strict';
  const core = globalThis.PuffPuzzle;
  const byId = id => document.getElementById(id);
  const stage = byId('stage');
  const tool = byId('tool');
  const balloonRoot = byId('balloons');
  const pullButton = byId('pull');
  const guide = byId('pull-guide');
  const finish = byId('finish');
  let state = core.fresh();
  let capturedPointer = null;
  let previousAnnouncement = '';
  const elements = new Map();
  const toPoint = event => {
    const rect = stage.getBoundingClientRect();
    return { x: (event.clientX - rect.left) / rect.width * core.WIDTH, y: (event.clientY - rect.top) / rect.height * core.HEIGHT };
  };
  function announce(message) {
    if (message !== previousAnnouncement) {
      byId('status').textContent = message;
      previousAnnouncement = message;
    }
  }
  for (const balloon of core.BALLOONS) {
    const element = document.createElement('article');
    element.className = `balloon${balloon.width < 220 ? ' balloon-small' : ''}`;
    element.style.cssText = `left:${balloon.x / core.WIDTH * 100}%;top:${balloon.y / core.HEIGHT * 100}%;width:${balloon.width / core.WIDTH * 100}%;height:${balloon.height / core.HEIGHT * 100}%;--balloon:${balloon.color};--valve-origin:${(balloon.valve.x - balloon.x) / balloon.width * 100}%;`;
    // All copy is fixed local data, never user or network input.
    element.innerHTML = `<div class="balloon-body"><div class="balloon-topline"><span>${balloon.label}</span><span class="badge">${balloon.badge}</span></div><h2>${balloon.title}</h2><p>${balloon.copy}</p><span class="balloon-progress" hidden></span></div><button class="valve" type="button" aria-label="${balloon.label} 노란 밸브. 선택해서 집게 끼우기."></button>`;
    const valve = element.querySelector('.valve');
    valve.style.left = `${(balloon.valve.x - balloon.x) / balloon.width * 100}%`;
    valve.style.top = `${(balloon.valve.y - balloon.y) / balloon.height * 100}%`;
    valve.addEventListener('click', () => {
      state = core.select(state, balloon.id);
      render();
      if (state.selected) pullButton.focus({ preventScroll: true });
    });
    element.querySelector('.balloon-body').addEventListener('click', () => {
      announce('풍선 몸통 대신 노란 밸브에 집게를 끼워요.');
      element.classList.remove('wobble');
      void element.offsetWidth;
      element.classList.add('wobble');
    });
    balloonRoot.append(element);
    elements.set(balloon.id, { element, valve, progress: element.querySelector('.balloon-progress') });
  }
  function render() {
    const completedBefore = !finish.hidden;
    for (const balloon of state.balloons) {
      const node = elements.get(balloon.id);
      const cleared = balloon.progress >= 1;
      node.element.classList.toggle('cleared', cleared);
      node.element.style.setProperty('--air', 1 - balloon.progress);
      node.element.setAttribute('aria-hidden', String(cleared));
      node.valve.disabled = cleared;
      node.valve.classList.toggle('selected', state.selected === balloon.id);
      node.valve.setAttribute('aria-pressed', String(state.selected === balloon.id));
      node.progress.hidden = !balloon.progress || cleared;
      node.progress.textContent = `공기 ${Math.round((1 - balloon.progress) * 100)}%`;
    }
    const count = state.balloons.filter(balloon => balloon.progress === 1).length;
    byId('counter').textContent = `정리 ${count} / 3`;
    tool.style.left = `${state.tool.x / core.WIDTH * 100}%`;
    tool.style.top = `${state.tool.y / core.HEIGHT * 100}%`;
    tool.classList.toggle('dragging', Boolean(state.drag));
    tool.classList.toggle('latched', Boolean(state.selected));
    tool.hidden = state.completed;
    pullButton.hidden = !state.selected || Boolean(state.drag) || state.completed;
    guide.classList.toggle('visible', Boolean(state.selected) && !state.completed);
    guide.style.left = `${Math.min(state.tool.x + 55, 316) / core.WIDTH * 100}%`;
    guide.style.top = `${Math.min(state.tool.y + 9, 542) / core.HEIGHT * 100}%`;
    finish.hidden = !state.completed;
    const messages = {
      ready: '파란 집게를 잡아 노란 밸브로 옮겨보세요.',
      grabbed: '노란 밸브 가까이 가져가면 집게가 끼워져요.',
      attached: '딸깍! 이제 집게를 아래로 쭉 당겨요. 소리 없이도 괜찮아요.',
      air: '공기가 빠지고 있어요. 아래로 조금 더 당겨요.',
      cleared: `후우! ${count}개 정리했어요. 다음 노란 밸브를 찾아보세요.`,
      paused: '빠진 공기는 그대로예요. 밸브에 다시 끼워 이어서 당겨요.',
      miss: '집게가 돌아왔어요. 노란 밸브 가까이 다시 가져가세요.',
    };
    announce(state.completed ? '세 개의 알림을 모두 정리했어요. 다시 부풀리기로 재시작할 수 있어요.' : messages[state.event]);
    byId('feedback-icon').textContent = state.completed ? '✓' : state.selected ? '↓' : '↗';
    if (state.completed && !completedBefore) byId('finish-title').focus({ preventScroll: true });
  }
  function releaseCapture() {
    // Relinquish ownership first: release may synchronously trigger loss events.
    const pointerId = capturedPointer;
    capturedPointer = null;
    if (pointerId !== null && tool.hasPointerCapture(pointerId)) {
      try { tool.releasePointerCapture(pointerId); }
      catch (error) { if (error.name !== 'NotFoundError') throw error; }
    }
  }
  function cancelInteraction() {
    if (!state.drag && !state.selected && capturedPointer === null) return;
    state = core.putDown(state);
    releaseCapture();
    render();
  }
  tool.addEventListener('pointerdown', event => {
    if (!event.isPrimary || event.button !== 0 || capturedPointer !== null) return;
    event.preventDefault();
    state = core.begin(state, toPoint(event), event.pointerId);
    if (!state.drag) return;
    capturedPointer = event.pointerId;
    try { tool.setPointerCapture(event.pointerId); }
    catch (error) {
      if (error.name !== 'NotFoundError' && error.name !== 'InvalidStateError') throw error;
      cancelInteraction();
      return;
    }
    tool.focus({ preventScroll: true });
    render();
  });
  tool.addEventListener('pointermove', event => {
    if (capturedPointer !== event.pointerId) return;
    if (event.buttons === 0 || event.clientX < 0 || event.clientY < 0 || event.clientX >= window.innerWidth || event.clientY >= window.innerHeight) {
      cancelInteraction();
      return;
    }
    state = core.move(state, toPoint(event), event.pointerId);
    if (!state.drag) releaseCapture();
    render();
  });
  const endPointer = event => {
    if (capturedPointer !== event.pointerId) return;
    state = core.end(state, event.pointerId);
    releaseCapture();
    render();
  };
  tool.addEventListener('pointerup', endPointer);
  tool.addEventListener('pointercancel', endPointer);
  tool.addEventListener('lostpointercapture', event => {
    if (capturedPointer !== event.pointerId) return;
    cancelInteraction();
  });
  tool.addEventListener('click', event => {
    // Pointer gestures already use pointerdown/move/up. Only keyboard or
    // assistive activation should select here; stale pointer clicks do nothing.
    if (event.detail !== 0) return;
    const next = state.balloons.find(balloon => balloon.progress < 1);
    if (next) state = core.select(state, next.id);
    render();
  });
  function pullOneStep() {
    const selectedBefore = state.selected;
    state = core.pull(state);
    render();
    if (selectedBefore && !state.selected && !state.completed) {
      const next = state.balloons.find(balloon => balloon.progress < 1);
      elements.get(next.id).valve.focus({ preventScroll: true });
    }
  }
  pullButton.addEventListener('click', pullOneStep);
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      state = core.putDown(state);
      releaseCapture();
      render();
      if (!state.completed) tool.focus({ preventScroll: true });
    } else if (state.selected && !state.drag && stage.closest('.game').contains(document.activeElement) && (event.key === 'ArrowDown' || event.key === ' ')) {
      event.preventDefault();
      pullOneStep();
    }
  });
  window.addEventListener('blur', cancelInteraction);
  window.addEventListener('pagehide', cancelInteraction);
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) cancelInteraction();
  });
  document.addEventListener('pointerout', event => {
    if (event.relatedTarget === null && event.pointerId === capturedPointer) cancelInteraction();
  });
  byId('restart').addEventListener('click', () => {
    state = core.fresh();
    releaseCapture();
    for (const { element } of elements.values()) element.classList.remove('wobble');
    render();
    tool.focus({ preventScroll: true });
  });
  render();
})();

