// No imports: this script also runs when index.html is opened directly via file://.
// Coordinates are logical units; the browser adapter maps the responsive stage.
(() => {
  'use strict';
  const WIDTH = 360;
  const HEIGHT = 620;
  const PULL_DISTANCE = 78;
  const SNAP_RADIUS = 34;
  const DOCK = Object.freeze({ x: 98, y: 565 });
  const BALLOONS = Object.freeze([
    Object.freeze({ id: 'flash', x: 36, y: 28, width: 282, height: 146, valve: Object.freeze({ x: 239, y: 184 }), color: '#f3a28f', label: '반짝 특가', badge: '99+', title: '지금! 지금! 지금!', copy: '놓치면 아쉬울 것 같은 기분만 드려요.' }),
    Object.freeze({ id: 'bonus', x: 12, y: 202, width: 238, height: 138, valve: Object.freeze({ x: 75, y: 350 }), color: '#eed887', label: '선물 도착', badge: '+999', title: '선물이 산더미!', copy: '열어도 열어도 알림이 또 와요.' }),
    Object.freeze({ id: 'vip', x: 136, y: 352, width: 206, height: 126, valve: Object.freeze({ x: 277, y: 488 }), color: '#c6b9df', label: '특별한 당신께', badge: 'VIP', title: '딱, 당신만요!', copy: '모두에게 똑같이 보낸 비밀 알림.' }),
  ]);
  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  const validPoint = point => point && Number.isFinite(point.x) && Number.isFinite(point.y);
  const active = (state, id) => state.balloons.find(balloon => balloon.id === id && balloon.progress < 1);
  const config = id => BALLOONS.find(balloon => balloon.id === id);
  const fresh = () => ({ balloons: BALLOONS.map(({ id }) => ({ id, progress: 0 })), tool: { ...DOCK }, drag: null, selected: null, event: 'ready', completed: false });
  function begin(state, point, pointerId = 1) {
    if (state.completed || state.drag || !validPoint(point)) return state;
    const selected = state.selected && active(state, state.selected);
    return { ...state, event: selected ? 'attached' : 'grabbed', drag: { pointerId, offsetX: point.x - state.tool.x, offsetY: point.y - state.tool.y, targetId: selected ? selected.id : null, anchorY: state.tool.y, toolBaseY: state.tool.y, startProgress: selected ? selected.progress : 0 } };
  }
  function updateProgress(state, id, progress, tool) {
    // Responsive coordinate conversion can yield 0.9999999999999993 for a full
    // pull. Snap only floating-point noise, never a visibly incomplete pull.
    const normalizedProgress = progress >= 1 - 1e-9 ? 1 : clamp(progress, 0, 1);
    const balloons = state.balloons.map(balloon => balloon.id === id ? { ...balloon, progress: normalizedProgress } : balloon);
    const cleared = balloons.find(balloon => balloon.id === id).progress === 1;
    return { ...state, balloons, tool: cleared ? { ...DOCK } : tool, drag: cleared ? null : state.drag, selected: cleared ? null : id, event: cleared ? 'cleared' : 'air', completed: balloons.every(balloon => balloon.progress === 1) };
  }
  function move(state, point, pointerId = 1) {
    const drag = state.drag;
    if (!drag || pointerId !== drag.pointerId || !validPoint(point)) return state;
    const rawTool = { x: point.x - drag.offsetX, y: point.y - drag.offsetY };
    const tool = { x: clamp(rawTool.x, 18, WIDTH - 18), y: clamp(rawTool.y, 20, HEIGHT - 24) };
    if (drag.targetId) {
      const target = active(state, drag.targetId);
      if (!target) return state;
      // Progress never reverses: releasing or moving upwards cannot reinflate an ad.
      const progress = Math.max(target.progress, drag.startProgress + Math.max(0, rawTool.y - drag.anchorY) / PULL_DISTANCE);
      return updateProgress(state, target.id, progress, { x: config(target.id).valve.x, y: drag.toolBaseY + (progress - drag.startProgress) * PULL_DISTANCE });
    }
    const nearest = BALLOONS.filter(balloon => active(state, balloon.id))
      .map(balloon => ({ balloon, distance: Math.hypot(tool.x - balloon.valve.x, tool.y - balloon.valve.y) }))
      .sort((a, b) => a.distance - b.distance)[0];
    if (nearest && nearest.distance <= SNAP_RADIUS) {
      return { ...state, selected: nearest.balloon.id, tool: { ...nearest.balloon.valve }, event: 'attached', drag: { ...drag, targetId: nearest.balloon.id, anchorY: tool.y, toolBaseY: nearest.balloon.valve.y, startProgress: active(state, nearest.balloon.id).progress } };
    }
    return { ...state, tool, event: 'grabbed' };
  }
  function end(state, pointerId = 1) {
    if (!state.drag || state.drag.pointerId !== pointerId) return state;
    return { ...state, tool: { ...DOCK }, selected: null, drag: null, event: state.drag.targetId ? 'paused' : 'miss' };
  }
  function select(state, id) {
    if (state.completed || state.drag || !active(state, id)) return state;
    return { ...state, selected: id, tool: { ...config(id).valve }, event: 'attached' };
  }
  function pull(state, amount = .25) {
    const target = active(state, state.selected);
    if (!target || state.drag || !Number.isFinite(amount) || amount <= 0) return state;
    const progress = target.progress + amount;
    return updateProgress(state, target.id, progress, { x: config(target.id).valve.x, y: config(target.id).valve.y + clamp(progress, 0, 1) * 50 });
  }
  function putDown(state) {
    if (state.completed) return state;
    return { ...state, tool: { ...DOCK }, drag: null, selected: null, event: 'paused' };
  }
  globalThis.PuffPuzzle = Object.freeze({ WIDTH, HEIGHT, PULL_DISTANCE, SNAP_RADIUS, DOCK, BALLOONS, fresh, begin, move, end, select, pull, putDown });
})();

