import test from 'node:test';
import assert from 'node:assert/strict';
import '../src/puzzle.js';

const game = globalThis.PuffPuzzle;
const progress = (state, id) => state.balloons.find(balloon => balloon.id === id).progress;
function latch(state, id, pointerId = 7) {
  const valve = game.BALLOONS.find(balloon => balloon.id === id).valve;
  const grabbed = game.begin(state, state.tool, pointerId);
  return game.move(grabbed, valve, pointerId);
}
function clearByDrag(state, id) {
  const attached = latch(state, id);
  return game.move(attached, { x: attached.tool.x, y: attached.tool.y + game.PULL_DISTANCE }, 7);
}

test('first scene contains three inflated ads and a reachable tool', () => {
  const state = game.fresh();
  assert.equal(state.balloons.length, 3);
  assert.ok(state.balloons.every(balloon => balloon.progress === 0));
  assert.deepEqual(state.tool, game.DOCK);
  assert.equal(state.completed, false);
  for (const balloon of game.BALLOONS) {
    assert.ok(balloon.valve.y + game.PULL_DISTANCE <= game.HEIGHT - 24, `${balloon.id} has room to pull`);
  }
});
test('moving without grabbing does not change state', () => {
  const state = game.fresh();
  assert.equal(game.move(state, game.BALLOONS[0].valve), state);
});
test('dragging toward a balloon body does not remove or attach it', () => {
  let state = game.begin(game.fresh(), game.DOCK, 7);
  state = game.move(state, { x: 160, y: 80 }, 7);
  assert.equal(state.selected, null);
  assert.equal(progress(state, 'flash'), 0);
  state = game.end(state, 7);
  assert.deepEqual(state.tool, game.DOCK);
  assert.equal(state.event, 'miss');
});
test('a valve snaps within the visible target allowance but does not clear on contact', () => {
  const valve = game.BALLOONS[0].valve;
  let state = game.begin(game.fresh(), game.DOCK, 7);
  state = game.move(state, { x: valve.x + game.SNAP_RADIUS - 1, y: valve.y }, 7);
  assert.equal(state.selected, 'flash');
  assert.equal(state.event, 'attached');
  assert.equal(progress(state, 'flash'), 0);
  assert.deepEqual(state.tool, valve);
});
test('contact outside the snap allowance stays unattached', () => {
  const valve = game.BALLOONS[0].valve;
  const state = game.move(game.begin(game.fresh(), game.DOCK), { x: valve.x + game.SNAP_RADIUS + 1, y: valve.y });
  assert.equal(state.selected, null);
});
test('the bottom valve can clear in one pull even when approached from below', () => {
  const valve = game.BALLOONS[2].valve;
  const contact = { x: valve.x, y: valve.y + game.SNAP_RADIUS - 1 };
  let state = game.move(game.begin(game.fresh(), game.DOCK, 7), contact, 7);
  assert.equal(state.selected, 'vip');
  const destination = { x: contact.x, y: contact.y + game.PULL_DISTANCE };
  assert.ok(destination.y < game.HEIGHT, 'full pull remains inside the stage');
  state = game.move(state, destination, 7);
  assert.equal(progress(state, 'vip'), 1);
});
test('half pull gives partial progress; upwards movement cannot undo it', () => {
  let state = latch(game.fresh(), 'flash');
  const valve = game.BALLOONS[0].valve;
  state = game.move(state, { x: valve.x, y: valve.y + game.PULL_DISTANCE / 2 }, 7);
  assert.equal(progress(state, 'flash'), .5);
  state = game.move(state, { x: valve.x, y: valve.y - 20 }, 7);
  assert.equal(progress(state, 'flash'), .5);
});
test('release or pointer cancellation preserves progress for another drag', () => {
  const valve = game.BALLOONS[0].valve;
  let state = latch(game.fresh(), 'flash');
  state = game.move(state, { x: valve.x, y: valve.y + 39 }, 7);
  state = game.end(state, 7);
  assert.equal(state.event, 'paused');
  assert.equal(progress(state, 'flash'), .5);
  assert.deepEqual(state.tool, game.DOCK);
  state = latch(state, 'flash');
  state = game.move(state, { x: valve.x, y: valve.y + 39 }, 7);
  assert.equal(progress(state, 'flash'), 1);
});
test('secondary pointer cannot hijack or release the held tool', () => {
  const state = game.begin(game.fresh(), game.DOCK, 41);
  assert.equal(game.begin(state, game.DOCK, 42), state);
  assert.equal(game.move(state, game.BALLOONS[0].valve, 42), state);
  assert.equal(game.end(state, 42), state);
});
test('grab offset is retained, so the handle does not jump to the fingertip', () => {
  let state = game.begin(game.fresh(), { x: game.DOCK.x + 12, y: game.DOCK.y + 10 }, 7);
  const valve = game.BALLOONS[0].valve;
  state = game.move(state, { x: valve.x + 12, y: valve.y + 10 }, 7);
  assert.equal(state.selected, 'flash');
  state = game.move(state, { x: valve.x + 12, y: valve.y + 10 + game.PULL_DISTANCE }, 7);
  assert.equal(progress(state, 'flash'), 1);
});
test('all three balloons can clear in a different order and finish once', () => {
  let state = game.fresh();
  for (const id of ['vip', 'flash', 'bonus']) state = clearByDrag(state, id);
  assert.equal(state.completed, true);
  assert.equal(state.drag, null);
  assert.equal(state.selected, null);
  assert.ok(state.balloons.every(balloon => balloon.progress === 1));
  assert.equal(game.begin(state, game.DOCK), state);
});
test('responsive coordinate noise does not prevent completion or hide a short pull', () => {
  const valve = game.BALLOONS[1].valve;
  const toLogicalY = value => value / game.HEIGHT * game.HEIGHT;
  let state = game.begin(game.fresh(), game.DOCK, 7);
  state = game.move(state, { x: valve.x, y: toLogicalY(valve.y) }, 7);
  state = game.move(state, { x: valve.x, y: toLogicalY(valve.y + game.PULL_DISTANCE - 1) }, 7);
  assert.ok(progress(state, 'bonus') < 1, 'one logical pixel short is still incomplete');
  state = game.move(state, { x: valve.x, y: toLogicalY(valve.y + game.PULL_DISTANCE) }, 7);
  assert.equal(progress(state, 'bonus'), 1);
});
test('cleared valves cannot be selected or attached again', () => {
  const state = clearByDrag(game.fresh(), 'flash');
  assert.equal(game.select(state, 'flash'), state);
  assert.equal(latch(state, 'flash').selected, null);
});
test('tap / keyboard alternative still requires attachment and four pulls', () => {
  let state = game.fresh();
  assert.equal(game.pull(state), state);
  state = game.select(state, 'bonus');
  assert.equal(progress(state, 'bonus'), 0);
  for (let i = 1; i <= 4; i++) {
    state = game.pull(state);
    assert.equal(progress(state, 'bonus'), i / 4);
  }
  assert.equal(state.selected, null);
});
test('switching from tap controls to dragging keeps both progress and handle position', () => {
  let state = game.pull(game.select(game.fresh(), 'vip'));
  const start = { ...state.tool };
  state = game.begin(state, start, 7);
  state = game.move(state, { x: start.x, y: start.y + 10 }, 7);
  assert.equal(state.tool.y, start.y + 10);
  assert.ok(progress(state, 'vip') > .25);
});
test('Esc-equivalent putDown preserves air already removed and ends dragging', () => {
  let state = game.pull(game.select(game.fresh(), 'flash'));
  state = game.putDown(game.begin(state, state.tool));
  assert.equal(progress(state, 'flash'), .25);
  assert.equal(state.drag, null);
  assert.equal(state.selected, null);
  assert.deepEqual(state.tool, game.DOCK);
});
test('a fresh restart has no leaked progress from prior rounds', () => {
  const previous = clearByDrag(game.fresh(), 'vip');
  const next = game.fresh();
  next.balloons[0].progress = .25;
  assert.equal(progress(previous, 'flash'), 0);
  assert.equal(progress(next, 'vip'), 0);
  assert.equal(game.fresh().balloons[0].progress, 0);
});
test('invalid inputs do not corrupt coordinates or progress', () => {
  const state = game.fresh();
  assert.equal(game.begin(state, { x: NaN, y: 1 }), state);
  assert.equal(game.select(state, 'unknown'), state);
  const selected = game.select(state, 'flash');
  assert.equal(game.pull(selected, -1), selected);
  assert.equal(game.pull(selected, NaN), selected);
});
